solution:
# 1. Basic arithmetic functions:
def add(a, b):
    return a + b

def subtract(a, b):
    return a - b

def multiply(a, b):
    return a * b

def divide(a, b):
    if b == 0:
        return 'Error: Cannot divide by zero'
    return a / b

# 2. Advanced functions:
def power(base, exponent):
    return base ** exponent

def square_root(number):
    if number < 0:
        return 'Error: Cannot calculate square root of negative number'
    return number ** 0.5

def percentage(part, whole):
    if whole == 0:
        return 0
    return (part / whole) * 100

# 3. Utility functions:
def is_even(number):
    return number % 2 == 0

def is_positive(number):
    return number > 0

def validate_number(input_str):
    try:
        return float(input_str)
    except ValueError:
        return 'Error: Please enter a valid number'

# 4. Main calculator function:
def calculate(operation, num1, num2=None):
    # Validate num1 if it's a string
    if isinstance(num1, str):
        num1 = validate_number(num1)
        if isinstance(num1, str):
            return num1

    # Validate num2 if provided and it's a string
    if num2 is not None and isinstance(num2, str):
        num2 = validate_number(num2)
        if isinstance(num2, str):
            return num2

    # Route to appropriate operation
    if operation == 'add':
        return add(num1, num2)
    elif operation == 'subtract':
        return subtract(num1, num2)
    elif operation == 'multiply':
        return multiply(num1, num2)
    elif operation == 'divide':
        return divide(num1, num2)
    elif operation == 'power':
        return power(num1, num2)
    elif operation == 'square_root':
        return square_root(num1)
    elif operation == 'percentage':
        return percentage(num1, num2)
    elif operation == 'is_even':
        return is_even(num1)
    elif operation == 'is_positive':
        return is_positive(num1)
    else:
        return 'Error: Unknown operation'

# 5. Test the calculator:
print('Testing basic operations:')
print('5 + 3 =', calculate('add', 5, 3))
print('10 - 4 =', calculate('subtract', 10, 4))
print('3 × 7 =', calculate('multiply', 3, 7))
print('15 ÷ 3 =', calculate('divide', 15, 3))
print('Divide by zero:', calculate('divide', 8, 0))

print('\nTesting advanced operations:')
print('2^3 =', calculate('power', 2, 3))
print('√25 =', calculate('square_root', 25))
print('30% of 150 =', calculate('percentage', 30, 150))
print('√(-9) =', calculate('square_root', -9))

print('\nTesting utility functions:')
print('Is 4 even?', calculate('is_even', 4))
print('Is -5 positive?', calculate('is_positive', -5))

print('\nTesting string inputs:')
print('add "10" + "5" =', calculate('add', '10', '5'))
print('Invalid input:', calculate('add', 'abc', 5))

print('\nTesting unknown operation:')
print('unknown op:', calculate('unknown', 5, 3))
